1448	+func distillEvalJudgeCacheKey(fact distillRawFactLine, agent, model, promptSHA string) string {
1449	+	sum := sha256.Sum256([]byte(strings.Join([]string{
1450	+		"gen-v1", fact.Text, fact.SessionID, agent, model, promptSHA,
1451	+	}, "\x00")))
1452	+	return hex.EncodeToString(sum[:])
