1455	+func distillEvalJudgeInput(sessionID string, facts []distillRawFactLine) []byte {
1456	+	var b strings.Builder
1457	+	fmt.Fprintf(&b, "SESSION: %s\n\nFACTS\n", sessionID)
1458	+	for i, f := range facts {
1459	+		fmt.Fprintf(&b, "%d [%s] [%s] %s\n", i+1, f.Kind, strings.Join(f.Paths, ","), f.Text)
1460	+	}
1461	+	return []byte(b.String())
1462	+}
