1464	+// parseDistillEvalJudgeOutput maps 1-based fact numbers to keep verdicts. Any
1465	+// fact the output misses or garbles stays kill — a judge hiccup must never
1466	+// inflate precision.
1467	+func parseDistillEvalJudgeOutput(output string, n int) []string {
1468	+	verdicts := make([]string, n)
1469	+	for i := range verdicts {
1470	+		verdicts[i] = "kill"
1471	+	}
1472	+	for _, raw := range strings.Split(output, "\n") {
1473	+		fields := strings.Fields(strings.TrimSpace(raw))
1474	+		if len(fields) < 2 {
1475	+			continue
1476	+		}
1477	+		idx, err := strconv.Atoi(fields[0])
1478	+		if err != nil || idx < 1 || idx > n {
1479	+			continue
1480	+		}
1481	+		if fields[1] == "keep" {
1482	+			verdicts[idx-1] = "keep"
1483	+		}
1484	+	}
1485	+	return verdicts
1486	+}
