1632	+func newDistillEvalCalibrateCommand(opts Options) *cobra.Command {
1633	+	var labelsPath, judgePath, out string
1634	+	cmd := &cobra.Command{
1635	+		Use:   "calibrate",
1636	+		Short: "Measure judge agreement against the golden labels",
1637	+		RunE: func(cmd *cobra.Command, args []string) error {
1638	+			labels, err := loadDistillEvalLabels(labelsPath)
1639	+			if err != nil {
1640	+				return err
1641	+			}
1642	+			judged, err := loadDistillEvalJudgeLines(judgePath)
1643	+			if err != nil {
1644	+				return err
1645	+			}
1646	+			var n, agree, kills, killAgree, keeps, keepAgree int
1647	+			for id, label := range labels {
1648	+				j, ok := judged[id]
1649	+				if !ok {
1650	+					continue
1651	+				}
1652	+				n++
1653	+				match := j.Verdict == label.Verdict
1654	+				if match {
1655	+					agree++
1656	+				}
1657	+				if label.Verdict == "kill" {
1658	+					kills++
1659	+					if match {
1660	+						killAgree++
1661	+					}
1662	+				} else {
1663	+					keeps++
1664	+					if match {
1665	+						keepAgree++
1666	+					}
1667	+				}
1668	+			}
1669	+			ratio := func(num, den int) float64 {
1670	+				if den == 0 {
1671	+					return 0
1672	+				}
1673	+				return float64(num) / float64(den)
1674	+			}
1675	+			cal := distillEvalCalibration{
1676	+				N:                n,
1677	+				Agreement:        ratio(agree, n),
1678	+				AgreementOnKills: ratio(killAgree, kills),
1679	+				AgreementOnKeeps: ratio(keepAgree, keeps),
1680	+			}
1681	+			data, err := json.MarshalIndent(cal, "", "  ")
1682	+			if err != nil {
1683	+				return err
1684	+			}
1685	+			if out == "" {
1686	+				out = filepath.Join(filepath.Dir(judgePath), "calibration.json")
1687	+			}
1688	+			if err := os.WriteFile(out, append(data, '\n'), 0o600); err != nil {
1689	+				return err
1690	+			}
1691	+			fmt.Fprintf(cmd.OutOrStdout(), "%s\n", data)
1692	+			return nil
1693	+		},
1694	+	}
1695	+	cmd.Flags().StringVar(&labelsPath, "labels", "", "Filled golden label sheet (required)")
1696	+	cmd.Flags().StringVar(&judgePath, "judge", "", "Judge verdicts file (required)")
1697	+	cmd.Flags().StringVar(&out, "out", "", "Calibration report path (default <judge-dir>/calibration.json)")
1698	+	_ = cmd.MarkFlagRequired("labels")
1699	+	_ = cmd.MarkFlagRequired("judge")
1700	+	return cmd
1701	+}
