1870	+// distillEvalLabelLine is one row of the golden label sheet: generated with an
1871	+// empty verdict, hand-filled by the owner with "keep" or "kill".
1872	+type distillEvalLabelLine struct {
1873	+	FactID         string   `json:"fact_id"`
1874	+	SessionID      string   `json:"session_id"`
1875	+	TranscriptPath string   `json:"transcript_path"`
1876	+	Kind           string   `json:"kind"`
1877	+	Paths          []string `json:"paths"`
1878	+	Text           string   `json:"text"`
1879	+	Verdict        string   `json:"verdict"`
1880	+	Reason         string   `json:"reason"`
1881	+}
1882	+
1883	+type distillEvalVerdict struct {
1884	+	Verdict string // "keep" | "kill"
1885	+	Reason  string
1886	+}
1887	+
1888	+// loadDistillEvalLabels reads a filled label sheet keyed by fact_id. Any
1889	+// verdict other than exactly "keep" or "kill" fails with its 1-based line
1890	+// number, so an unfilled or typoed sheet never silently scores as empty.
1891	+func loadDistillEvalLabels(path string) (map[string]distillEvalVerdict, error) {
1892	+	f, err := os.Open(path)
1893	+	if err != nil {
1894	+		return nil, err
1895	+	}
1896	+	defer f.Close()
1897	+	labels := map[string]distillEvalVerdict{}
1898	+	sc := bufio.NewScanner(f)
1899	+	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
1900	+	lineNo := 0
1901	+	for sc.Scan() {
1902	+		lineNo++
1903	+		if len(sc.Bytes()) == 0 {
1904	+			continue
1905	+		}
1906	+		var line distillEvalLabelLine
1907	+		if err := json.Unmarshal(sc.Bytes(), &line); err != nil {
1908	+			return nil, fmt.Errorf("%s line %d: %w", path, lineNo, err)
1909	+		}
1910	+		if line.Verdict != "keep" && line.Verdict != "kill" {
1911	+			return nil, fmt.Errorf("%s line %d: verdict must be exactly \"keep\" or \"kill\", got %q", path, lineNo, line.Verdict)
1912	+		}
1913	+		if line.FactID == "" {
1914	+			return nil, fmt.Errorf("%s line %d: missing fact_id", path, lineNo)
1915	+		}
1916	+		labels[line.FactID] = distillEvalVerdict{Verdict: line.Verdict, Reason: line.Reason}
1917	+	}
1918	+	if err := sc.Err(); err != nil {
1919	+		return nil, err
1920	+	}
1921	+	return labels, nil
1922	+}
