1924	+// readDistillEvalRawFacts loads the fact lines (type "fact") of a run's
1925	+// raw-facts.jsonl, plus the chunk lines (type "chunk") for callers that need
1926	+// them.
1927	+func readDistillEvalRawFacts(path string) (chunks []distillRawChunkLine, facts []distillRawFactLine, err error) {
1928	+	f, err := os.Open(path)
1929	+	if err != nil {
1930	+		return nil, nil, err
1931	+	}
1932	+	defer f.Close()
1933	+	sc := bufio.NewScanner(f)
1934	+	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
1935	+	for sc.Scan() {
1936	+		if len(sc.Bytes()) == 0 {
1937	+			continue
1938	+		}
1939	+		var probe struct {
1940	+			Type string `json:"type"`
1941	+		}
1942	+		if err := json.Unmarshal(sc.Bytes(), &probe); err != nil {
1943	+			return nil, nil, fmt.Errorf("%s: %w", path, err)
1944	+		}
1945	+		switch probe.Type {
1946	+		case "chunk":
1947	+			var c distillRawChunkLine
1948	+			if err := json.Unmarshal(sc.Bytes(), &c); err != nil {
1949	+				return nil, nil, err
1950	+			}
1951	+			chunks = append(chunks, c)
1952	+		case "fact":
1953	+			var fl distillRawFactLine
1954	+			if err := json.Unmarshal(sc.Bytes(), &fl); err != nil {
1955	+				return nil, nil, err
1956	+			}
1957	+			facts = append(facts, fl)
1958	+		}
1959	+	}
1960	+	return chunks, facts, sc.Err()
1961	+}
