2172	+// distillEvalExec is the shell-out seam: every child process the eval harness
2173	+// spawns (refresh sessions, distill) goes through it so tests can intercept.
2174	+// The child is the current binary; env replaces the process environment.
2175	+var distillEvalExec = func(ctx context.Context, dir string, env []string, args ...string) ([]byte, error) {
2176	+	exe, err := os.Executable()
2177	+	if err != nil {
2178	+		return nil, fmt.Errorf("resolve own executable: %w", err)
2179	+	}
2180	+	cmd := exec.CommandContext(ctx, exe, args...)
2181	+	cmd.Dir = dir
2182	+	cmd.Env = env
2183	+	out, err := cmd.CombinedOutput()
2184	+	if err != nil {
2185	+		tail := out
2186	+		if len(tail) > 2000 {
2187	+			tail = tail[len(tail)-2000:]
2188	+		}
2189	+		return out, fmt.Errorf("%s: %w\n%s", args[0], err, tail)
2190	+	}
2191	+	return out, nil
2192	+}
