2194	+// distillEvalChildEnv builds the child environment: the parent's, minus any
2195	+// XDG data/state/cache and distill override leakage, plus the sandbox and the
2196	+// variant's overrides. XDG_CONFIG_HOME is inherited on purpose — the child's
2197	+// agent (claude/codex) needs the user's auth and config.
2198	+func distillEvalChildEnv(sandbox string, extra map[string]string) []string {
2199	+	drop := map[string]bool{
2200	+		"XDG_DATA_HOME": true, "XDG_STATE_HOME": true, "XDG_CACHE_HOME": true,
2201	+		envDistillTemplate: true, envFactsMaxPerChunk: true,
2202	+	}
2203	+	var env []string
2204	+	for _, kv := range os.Environ() {
2205	+		key, _, ok := strings.Cut(kv, "=")
2206	+		if ok && drop[key] {
2207	+			continue
2208	+		}
2209	+		env = append(env, kv)
2210	+	}
2211	+	env = append(env,
2212	+		"XDG_DATA_HOME="+filepath.Join(sandbox, "data"),
2213	+		"XDG_STATE_HOME="+filepath.Join(sandbox, "state"),
2214	+		"XDG_CACHE_HOME="+filepath.Join(sandbox, "cache"),
2215	+	)
2216	+	keys := make([]string, 0, len(extra))
2217	+	for k := range extra {
2218	+		keys = append(keys, k)
2219	+	}
2220	+	sort.Strings(keys)
2221	+	for _, k := range keys {
2222	+		env = append(env, k+"="+extra[k])
2223	+	}
2224	+	return env
2225	+}
