2855	+// distillEvalWordJaccard is the near-duplicate test: lowercase word-set
2856	+// Jaccard. ponytail: naive text similarity with a fixed 0.5 threshold; the
2857	+// upgrade path is the BM25 ranker if this proves too coarse.
2858	+func distillEvalWordJaccard(a, b string) float64 {
2859	+	setOf := func(s string) map[string]bool {
2860	+		set := map[string]bool{}
2861	+		for _, w := range strings.Fields(strings.ToLower(s)) {
2862	+			set[w] = true
2863	+		}
2864	+		return set
2865	+	}
2866	+	sa, sb := setOf(a), setOf(b)
2867	+	if len(sa) == 0 || len(sb) == 0 {
2868	+		return 0
2869	+	}
2870	+	inter := 0
2871	+	for w := range sa {
2872	+		if sb[w] {
2873	+			inter++
2874	+		}
2875	+	}
2876	+	union := len(sa) + len(sb) - inter
2877	+	return float64(inter) / float64(union)
2878	+}
