3018	+func distillEvalReadCallTrace(path string) (tokens, calls map[string]int, err error) {
3019	+	tokens, calls = map[string]int{}, map[string]int{}
3020	+	f, err := os.Open(path)
3021	+	if err != nil {
3022	+		if os.IsNotExist(err) {
3023	+			return tokens, calls, nil
3024	+		}
3025	+		return nil, nil, err
3026	+	}
3027	+	defer f.Close()
3028	+	sc := bufio.NewScanner(f)
3029	+	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
3030	+	for sc.Scan() {
3031	+		if len(sc.Bytes()) == 0 {
3032	+			continue
3033	+		}
3034	+		var rec struct {
3035	+			Session      string `json:"session"`
3036	+			InputTokens  int    `json:"input_tokens"`
3037	+			OutputTokens int    `json:"output_tokens"`
3038	+		}
3039	+		if err := json.Unmarshal(sc.Bytes(), &rec); err != nil {
3040	+			return nil, nil, fmt.Errorf("%s: %w", path, err)
3041	+		}
3042	+		if rec.Session == "" {
3043	+			continue
3044	+		}
3045	+		calls[rec.Session]++
3046	+		tokens[rec.Session] += rec.InputTokens + rec.OutputTokens
3047	+	}
3048	+	return tokens, calls, sc.Err()
3049	+}
